<script setup lang="ts">
import { computed, ref } from 'vue'
import type { Activity, ActivityDraft } from '../data/activities'

const props = defineProps<{ activity: Activity; draft: ActivityDraft; locked: boolean }>()
const emit = defineEmits<{ update: [draft: ActivityDraft] }>()
const picked = ref(''), mapStart = ref(''), openedMessage = ref(''), demoIndex = ref(0)
const dispositions = [{id:'routine',label:'Звичайна робота',icon:'▤'}, {id:'verify',label:'Незалежна перевірка',icon:'⌕'}, {id:'report',label:'Повідомити про інцидент',icon:'⚑'}]
const nodeTypes = [{id:'evidence',label:'Що спостерігаю',icon:'⌕'}, {id:'risk',label:'Що це означає',icon:'△'}, {id:'action',label:'Як дію',icon:'↗'}]
const textValue = (id: string) => props.draft.text[id] ?? ''
const textLength = (id: string) => textValue(id).trim().length
const selectedMail = computed(() => props.activity.kind === 'triage' ? props.activity.messages.find(item => item.id === openedMessage.value) ?? props.activity.messages[0] : undefined)
const update = (patch: Partial<ActivityDraft>) => { if (!props.locked) emit('update',{...props.draft,...patch}) }
function write(id: string,event: Event) { update({text:{...props.draft.text,[id]:(event.target as HTMLTextAreaElement).value}}) }
function toggle(field: 'selectedEvidence'|'flagged'|'checks',id: string) { const values = props.draft[field]; update({[field]:values.includes(id) ? values.filter(value => value !== id) : [...values,id]}) }
function classify(id: string,group: string) { update({classification:{...props.draft.classification,[id]:group}}); picked.value = '' }
function drop(event: DragEvent,group: string) { event.preventDefault(); const id = event.dataTransfer?.getData('text/plain'); if (props.activity.kind === 'classify' && id && props.activity.items.some(item => item.id === id)) classify(id,group) }
function drag(event: DragEvent,id: string) { event.dataTransfer?.setData('text/plain',id); picked.value = id }
function act(id: string) { if (!props.draft.actions.includes(id)) update({actions:[...props.draft.actions,id]}) }
function actionEffect(id: string,position: number) {
  if (props.activity.kind !== 'simulation') return ''
  const missing = (props.activity.dependencies ?? []).filter(item => item.after === id && !props.draft.actions.slice(0,position).includes(item.before))
  if (missing.length) return `Дію виконано зарано. Ще не підготовлено: ${missing.map(item => props.activity.kind === 'simulation' ? props.activity.tools.find(tool => tool.id === item.before)?.label : '').join('; ')}. Перегляньте порядок дій, щоб отримати потрібний результат.`
  return props.activity.tools.find(tool => tool.id === id)?.effect ?? ''
}
function connect(id: string) { if (props.locked) return; if (!mapStart.value) mapStart.value = id; else if (mapStart.value === id) mapStart.value = ''; else { const link = `${mapStart.value}>${id}`; if (!props.draft.links.includes(link)) update({links:[...props.draft.links,link]}); mapStart.value = '' } }
function nodeLabel(id: string) { return props.activity.kind === 'map' ? props.activity.nodes.find(item => item.id === id)?.label ?? id : id }
function routeMail(disposition: string) { if (selectedMail.value) update({triage:{...props.draft.triage,[selectedMail.value.id]:disposition}}) }
</script>

<template>
  <div class="workbench" :class="`tool-${activity.kind}`">
    <template v-if="activity.kind === 'classify'">
      <div class="tool-instruction"><span aria-hidden="true">▦</span><p>Перетягніть картки до робочих зон або скористайтеся меню на картці. Класифікуйте кожен об’єкт.</p></div>
      <div class="sorting-pool"><span class="tool-label">НЕРОЗПОДІЛЕНІ ОБ’ЄКТИ · {{ activity.items.filter(item => !draft.classification[item.id]).length }}</span><div class="sort-items"><article v-for="item in activity.items.filter(item => !draft.classification[item.id])" :key="item.id" class="sort-item" :draggable="!locked" @dragstart="drag($event,item.id)"><span aria-hidden="true">⠿</span><strong>{{ item.label }}</strong><select :aria-label="`Перемістити: ${item.label}`" :disabled="locked" :value="draft.classification[item.id] ?? ''" @change="classify(item.id,($event.target as HTMLSelectElement).value)"><option value="">Оберіть зону…</option><option v-for="group in activity.groups" :key="group.id" :value="group.id">{{ group.label }}</option></select></article><p v-if="activity.items.every(item => draft.classification[item.id])" class="quiet-note">Усі об’єкти розподілено. Перегляньте свої зони перед розбором.</p></div></div>
      <div class="sorting-zones"><section v-for="group in activity.groups" :key="group.id" class="sorting-zone" @dragover.prevent @drop="drop($event,group.id)"><h3>{{ group.label }}<span>{{ activity.items.filter(item => draft.classification[item.id] === group.id).length }}</span></h3><p v-if="!activity.items.some(item => draft.classification[item.id] === group.id)" class="drop-label">Перетягніть сюди об’єкти</p><article v-for="item in activity.items.filter(item => draft.classification[item.id] === group.id)" :key="item.id" class="sorted-item" :draggable="!locked" @dragstart="drag($event,item.id)"><strong>{{ item.label }}</strong><select :aria-label="`Змінити зону: ${item.label}`" :disabled="locked" :value="group.id" @change="classify(item.id,($event.target as HTMLSelectElement).value)"><option value="">Повернути до об’єктів</option><option v-for="other in activity.groups" :key="other.id" :value="other.id">{{ other.label }}</option></select></article></section></div>
    </template>

    <template v-else-if="activity.kind === 'evidence'">
      <div class="mail-window"><div class="window-bar"><i></i><i></i><i></i><span>РОБОЧА ПОШТА / ДОКУМЕНТ ДЛЯ АНАЛІЗУ</span></div><div class="mail-content"><span class="tool-label">ВІДПРАВНИК</span><p class="sender">{{ activity.mail.from }}</p><h3>{{ activity.mail.subject }}</h3><p class="mail-body">{{ activity.mail.body }}</p><div class="address"><span aria-hidden="true">↗</span><code>{{ activity.mail.url }}</code><small>адреса з повідомлення</small></div></div></div>
      <div class="tool-instruction"><span aria-hidden="true">⌕</span><p>Позначте деталі, які використаєте як докази. Серед них є деталі, що не доводять ризик.</p></div><div class="evidence-grid"><button v-for="item in activity.evidence" :key="item.id" type="button" :disabled="locked" :aria-pressed="draft.selectedEvidence.includes(item.id)" :class="{marked:draft.selectedEvidence.includes(item.id)}" @click="toggle('selectedEvidence',item.id)"><span>{{ draft.selectedEvidence.includes(item.id) ? '✓ ДО ДОСЬЄ' : '+ ДОСЛІДИТИ' }}</span><strong>{{ item.label }}</strong><p>{{ item.detail }}</p></button></div>
      <div class="writing-block"><label :for="`${activity.id}-reason`">{{ activity.reasonPrompt }}</label><textarea :id="`${activity.id}-reason`" :value="textValue('reason')" :disabled="locked" rows="3" maxlength="2000" placeholder="Пов’яжіть спостереження з висновком власними словами…" @input="write('reason',$event)"></textarea><small>{{ textLength('reason') }} / 30 символів мінімум · аргументацію обговоріть із викладачем</small></div>
    </template>

    <template v-else-if="activity.kind === 'simulation'">
      <div class="sim-header"><div><span class="status-dot"></span> НАВЧАЛЬНЕ РОБОЧЕ СЕРЕДОВИЩЕ</div><span>{{ draft.actions.length }} виконаних дій</span></div><div class="sim-layout"><section class="control-panel"><h3>Панель керування</h3><p>Оберіть інструмент і виконайте потрібні дії в обґрунтованому порядку.</p><button v-for="tool in activity.tools" :key="tool.id" type="button" :disabled="locked || draft.actions.includes(tool.id)" @click="act(tool.id)"><span aria-hidden="true">{{ draft.actions.includes(tool.id) ? '✓' : '↗' }}</span><div><strong>{{ tool.label }}</strong><small>{{ tool.detail }}</small></div></button></section><section class="action-log" aria-live="polite"><div class="log-head"><h3>Журнал наслідків</h3><button type="button" :disabled="locked || !draft.actions.length" @click="update({actions:[]})">Почати заново</button></div><div v-if="!draft.actions.length" class="log-empty"><span aria-hidden="true">◷</span><p>Дії з’являться тут у тому порядку, у якому ви їх виконаєте.</p></div><ol><li v-for="(id,i) in draft.actions" :key="id"><span>{{ String(i + 1).padStart(2,'0') }}</span><div><strong>{{ activity.tools.find(tool => tool.id === id)?.label }}</strong><p>{{ actionEffect(id,i) }}</p></div></li></ol></section></div>
    </template>

    <template v-else-if="activity.kind === 'map'">
      <div class="tool-instruction"><span aria-hidden="true">⤳</span><p>Оберіть початковий вузол, потім вузол наслідку. Побудуйте ланцюги «доказ → ризик → дія». Зайві зв’язки можна видалити.</p></div><p class="map-status" role="status">{{ mapStart ? `Початок: ${nodeLabel(mapStart)}. Оберіть, що з нього випливає.` : 'Оберіть перший вузол для нового зв’язку.' }}</p><div class="map-columns"><section v-for="type in nodeTypes" :key="type.id"><h3><span aria-hidden="true">{{ type.icon }}</span>{{ type.label }}</h3><button v-for="node in activity.nodes.filter(node => node.type === type.id)" :key="node.id" type="button" :disabled="locked" :class="{selected:mapStart === node.id,linked:draft.links.some(link => link.split('>').includes(node.id))}" :aria-pressed="mapStart === node.id" @click="connect(node.id)">{{ node.label }}<span aria-hidden="true">{{ mapStart === node.id ? '●' : '○' }}</span></button></section></div><div class="connections"><span class="tool-label">ВАША КАРТА · {{ draft.links.length }} ЗВ’ЯЗКІВ</span><p v-if="!draft.links.length" class="quiet-note">З’єднайте факти, їх значення та професійні дії.</p><div v-for="link in draft.links" :key="link" class="connection"><span>{{ nodeLabel(link.split('>')[0]!) }}</span><i aria-hidden="true">→</i><span>{{ nodeLabel(link.split('>')[1]!) }}</span><button type="button" :disabled="locked" :aria-label="`Видалити зв’язок ${nodeLabel(link.split('>')[0]!)} → ${nodeLabel(link.split('>')[1]!)}`" @click="update({links:draft.links.filter(value => value !== link)})">×</button></div></div><div class="writing-block"><label :for="`${activity.id}-reason`">Поясніть, як ваші зв’язки допомагають прийняти рішення.</label><textarea :id="`${activity.id}-reason`" :value="textValue('reason')" :disabled="locked" rows="3" maxlength="2000" placeholder="Цей доказ означає…, тому я…" @input="write('reason',$event)"></textarea><small>{{ textLength('reason') }} / 30 символів мінімум · текст для обговорення з викладачем</small></div>
    </template>

    <template v-else-if="activity.kind === 'review'">
      <div class="document-head"><span aria-hidden="true">▤</span><div><span class="tool-label">ПРОЄКТ ІНСТРУКЦІЇ · НА РЕЦЕНЗУВАННЯ</span><h3>Аудит перед передаванням колегам</h3></div></div><p class="quiet-note">Позначте кроки, які потрібно виправити, і підготуйте власну редакцію.</p><div class="review-plan"><button v-for="(line,i) in activity.plan" :key="line.id" type="button" :disabled="locked" :aria-pressed="draft.flagged.includes(line.id)" :class="{flagged:draft.flagged.includes(line.id)}" @click="toggle('flagged',line.id)"><span>{{ String(i + 1).padStart(2,'0') }}</span><p>{{ line.text }}</p><small>{{ draft.flagged.includes(line.id) ? '⚑ ВИПРАВИТИ' : '+ ПОЗНАЧИТИ' }}</small></button></div><div class="writing-block"><label :for="`${activity.id}-revision`">{{ activity.revisionPrompt }}</label><textarea :id="`${activity.id}-revision`" :value="textValue('revision')" :disabled="locked" rows="5" maxlength="3000" placeholder="Напишіть безпечні формулювання та поясніть, чому змінюєте ці кроки…" @input="write('revision',$event)"></textarea><small>{{ textLength('revision') }} / 40 символів мінімум · авторську редакцію оцінює викладач</small></div>
    </template>

    <template v-else-if="activity.kind === 'compose'">
      <div class="document-head"><span aria-hidden="true">✎</span><div><span class="tool-label">АВТОРСЬКА МАЙСТЕРНЯ</span><h3>Створіть рішення для своєї команди</h3></div></div><div class="composer-layout"><div><div v-for="section in activity.sections" :key="section.id" class="writing-block"><label :for="`${activity.id}-${section.id}`">{{ section.label }}</label><p class="field-prompt">{{ section.prompt }}</p><textarea :id="`${activity.id}-${section.id}`" :value="textValue(section.id)" :disabled="locked" rows="3" maxlength="3000" @input="write(section.id,$event)"></textarea><small>{{ textLength(section.id) }} / {{ section.minLength }} символів мінімум</small></div></div><aside class="live-document"><span class="tool-label">ПЕРЕДПЕРЕГЛЯД ВАШОГО ДОКУМЕНТА</span><h3>{{ activity.title }}</h3><section v-for="section in activity.sections" :key="section.id"><strong>{{ section.label }}</strong><p>{{ textValue(section.id) || 'Ваш текст з’явиться тут…' }}</p></section></aside></div><fieldset class="self-check"><legend>Перевірте власний продукт перед передаванням</legend><label v-for="check in activity.checklist" :key="check.id"><input type="checkbox" :checked="draft.checks.includes(check.id)" :disabled="locked" @change="toggle('checks',check.id)"><span>{{ check.label }}</span></label><p>Це ваша самооцінка. Зміст і якість рішення обговоріть із викладачем.</p></fieldset>
    </template>

    <template v-else-if="activity.kind === 'briefing'">
      <div class="brief-panels"><article v-for="(panel,i) in activity.panels" :key="panel.title"><span>{{ String(i + 1).padStart(2,'0') }}</span><div><h3>{{ panel.title }}</h3><p>{{ panel.text }}</p></div></article></div><section v-if="activity.demonstration?.length" class="demonstration"><span class="tool-label">ПОКРОКОВА ДЕМОНСТРАЦІЯ НАСТАВНИКА</span><div class="demo-steps"><button v-for="(step,i) in activity.demonstration" :key="step.label" type="button" :class="{selected:demoIndex === i}" :aria-pressed="demoIndex === i" @click="demoIndex = i">{{ i + 1 }}</button></div><h3>{{ activity.demonstration[demoIndex]?.label }}</h3><p>{{ activity.demonstration[demoIndex]?.detail }}</p><button v-if="demoIndex < activity.demonstration.length - 1" type="button" class="inline-button" @click="demoIndex++">Наступний крок демонстрації →</button></section>
    </template>

    <template v-else-if="activity.kind === 'triage'">
      <div class="inbox-toolbar"><span aria-hidden="true">▣</span><strong>ПОШТА ПРАКТИКАНТА</strong><span>{{ Object.values(draft.triage).filter(Boolean).length }} / {{ activity.messages.length }} опрацьовано</span></div><div class="inbox-layout"><nav class="message-list" aria-label="Навчальні листи"><button v-for="message in activity.messages" :key="message.id" type="button" :class="{selected:selectedMail?.id === message.id}" @click="openedMessage = message.id"><strong>{{ message.from }}</strong><span>{{ message.subject }}</span><small>{{ dispositions.find(item => item.id === draft.triage[message.id])?.label ?? 'НЕ ОПРАЦЬОВАНО' }}</small></button></nav><section v-if="selectedMail" class="opened-mail"><span class="tool-label">{{ selectedMail.from }}</span><h3>{{ selectedMail.subject }}</h3><p>{{ selectedMail.body }}</p><div class="address"><code>{{ selectedMail.url }}</code></div><div class="mail-routing"><span class="tool-label">ПЕРЕМІСТИТИ В РОБОЧУ ПАПКУ</span><button v-for="folder in dispositions" :key="folder.id" type="button" :disabled="locked" :aria-pressed="draft.triage[selectedMail.id] === folder.id" :class="{routed:draft.triage[selectedMail.id] === folder.id}" @click="routeMail(folder.id)"><span aria-hidden="true">{{ folder.icon }}</span>{{ folder.label }}</button></div></section></div><p class="quiet-note">Папка «Незалежна перевірка» означає, що ви уточните запит через відомий канал; папка інциденту — що передасте повідомлення відповідальній особі.</p>
    </template>
  </div>
</template>

<style scoped>
.workbench{--border:#35445c;color:#e6edf7;font-size:13px}button,input,select,textarea{font:inherit}button{cursor:pointer}button:disabled{cursor:default;opacity:.6}button:focus-visible,select:focus-visible,input:focus-visible,textarea:focus-visible{outline:2px solid var(--accent);outline-offset:3px}button{color:inherit}.tool-label{font-size:9px;letter-spacing:.12em;font-weight:800;color:#95a9c7}.tool-instruction{display:flex;gap:13px;padding:14px 17px;background:#1e2d43;border-radius:9px;margin:17px 0;color:#b9cbe3;line-height:1.6}.tool-instruction>span{color:var(--accent);font-size:22px;flex:none}.tool-instruction p{margin:0;font-size:12px}.quiet-note{color:#8fa4c4;font-size:11px;line-height:1.7}.sorting-pool{border:1px solid var(--border);border-radius:12px;padding:16px;background:#111c2c}.sort-items{display:grid;gap:8px;margin-top:12px}.sort-item{display:flex;gap:9px;align-items:center;background:#223047;padding:12px;border-radius:7px;min-width:0}.sort-item>span{color:#8299bc;font-size:20px}.sort-item strong{font-size:12px;flex:1}.sort-item select,.sorted-item select{background:#101c2d;color:#becde2;border:1px solid #435573;border-radius:6px;padding:8px;font-size:10px;max-width:48%}.sorting-zones{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:15px}.sorting-zone{padding:15px;background:color-mix(in srgb,var(--accent) 4%,#152235);border:1px dashed #50617c;border-radius:12px;min-height:140px}.sorting-zone h3{display:flex;gap:12px;justify-content:space-between;color:var(--accent);font-size:12px;margin:0 0 12px}.sorting-zone h3 span{color:#aebfd9;font-size:10px}.drop-label{color:#7f95b7;font-size:11px;text-align:center;margin-top:25px}.sorted-item{display:grid;gap:9px;padding:12px;background:#22334d;border-radius:8px;margin-top:8px}.sorted-item strong{font-size:12px;line-height:1.5}.sorted-item select{max-width:100%;width:100%}.mail-window{border:1px solid #40516c;border-radius:12px;overflow:hidden;background:#111c2c}.window-bar{display: